9. 다음 알고리즘에 해당하는 정렬은?
sort(arr[], n){ // arr 배열의 인덱스는 0 ～ n-1
for i ← 1 to n - 1 {
cur ← arr[i];
j ← i – 1;
while (j ≧ 0) and (arr[j] > cur) {
arr[j + 1] ← arr[j];
j ← j – 1;
}
arr[j + 1] ← cur;
}
}

